<?php
$ratingStmt = db()->prepare("SELECT AVG(note) AS average, COUNT(*) AS total FROM avis_terrains WHERE terrain_id=:id AND statut='publie'");
$ratingStmt->execute(['id'=>$land['id']]);
$terrainRating = $ratingStmt->fetch();
$reviewStmt = db()->prepare("SELECT nom,note,commentaire,date_creation FROM avis_terrains WHERE terrain_id=:id AND statut='publie' ORDER BY date_creation DESC LIMIT 12");
$reviewStmt->execute(['id'=>$land['id']]);
$terrainReviews = $reviewStmt->fetchAll();
?>
<section class="reviews-section" id="reviews"><div class="reviews-heading"><div><span class="eyebrow">AVIS CLIENTS</span><h2>Les expériences partagées</h2></div><?= star_rating((float)($terrainRating['average'] ?? 0),(int)$terrainRating['total']) ?></div><div class="review-columns"><div class="review-list"><?php if ($terrainReviews): foreach ($terrainReviews as $review): ?><article class="review-card"><div class="review-card-head"><strong><?= e($review['nom']) ?></strong><?= star_rating((float)$review['note']) ?></div><p><?= nl2br(e($review['commentaire'])) ?></p><time><?= e(date('d/m/Y', strtotime($review['date_creation']))) ?></time></article><?php endforeach; else: ?><p class="empty-reviews">Aucun avis publié pour ce bien. Soyez le premier à partager votre expérience.</p><?php endif; ?></div><?php if ($land['statut'] !== 'vendu'): ?><form class="review-form glass-filter" method="post" action="?page=terrain&id=<?= (int)$land['id'] ?>#reviews"><?= csrf_field() ?><input type="hidden" name="action" value="submit_review"><input type="hidden" name="type_cible" value="terrain"><input type="hidden" name="terrain_id" value="<?= (int)$land['id'] ?>"><label class="honeypot" aria-hidden="true">Ne pas remplir<input name="website" tabindex="-1" autocomplete="off"></label><span class="eyebrow">VOTRE RETOUR</span><h3>Évaluez ce bien</h3><label>Votre nom<input name="nom" maxlength="120" required autocomplete="name"></label><fieldset class="star-picker"><legend>Votre note</legend><?php for ($star=5;$star>=1;$star--): ?><label><input type="radio" name="note" value="<?= $star ?>" required><span aria-label="<?= $star ?> sur 5">★</span></label><?php endfor; ?></fieldset><label>Votre avis<textarea name="commentaire" maxlength="2000" rows="4" required placeholder="Partagez votre expérience..."></textarea></label><button class="button button-green">Envoyer pour modération <span>↗</span></button><small>Votre avis sera publié après vérification par notre équipe.</small></form><?php endif; ?></div></section>